/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-02: auth.publicRoute() exposed to nodes and plugins (httpAdminNodeRoutes)
 *   #63: the limit of the JSON and urlencoded parsers of the Admin API is at most the maximum string length
 * This notice is required by section 4(b) of the Apache License 2.0.
 */


 /**
  * This module provides an Express application to serve the Node-RED editor.
  *
  * It implements the Node-RED HTTP Admin API the Editor uses to interact
  * with the Node-RED runtime.
  *
  * @namespace @node-red/editor-api
  */

const bodyParser = require("body-parser");
const passport = require('passport');
const cors = require('cors');
var auth = require("./auth");
var apiUtil = require("./util");

var adminApp;
var server;
var editor;

// The size limit of the JSON and urlencoded parsers (#63). TWIN: `bodyParserLimit` and
// `bodyParserLimitBytes` of nodes/core/network/21-httpin.js (the parsers of "http in")
// hold the same rule and must stay equal to this copy; the shared case table
// test/resources/body-parser-limit-cases.js is run against both. The rule follows the
// size parser of body-parser 1.20.8 (the `bytes` module; the version is pinned in
// editor-api/package.json and nodes/package.json): a body-parser upgrade needs both
// copies checked against the table again. (`bytes` is not a dependency of this package.)
const MAX_STRING_LENGTH = require("buffer").constants.MAX_STRING_LENGTH;
const SIZE_UNITS = { b: 1, kb: 1024, mb: Math.pow(1024, 2), gb: Math.pow(1024, 3), tb: Math.pow(1024, 4), pb: Math.pow(1024, 5) };

/**
 * The size in bytes that the JSON and urlencoded body parsers take from their `limit`
 * option, by the rules of the size parser they use (the `bytes` module): a number
 * that is not NaN as it is; a string of a number with a unit (kb, mb, gb, tb, pb;
 * 1024 based; an optional sign, spaces before the unit), otherwise the leading
 * integer of the string, as bytes; null for anything else.
 * @param {*} value
 * @returns {number|null}
 */
function bodyParserLimitBytes(value) {
    if (typeof value === "number") {
        return isNaN(value) ? null : value;
    }
    if (typeof value !== "string") { return null; }
    var withUnit = /^([-+]?\d+(?:\.\d+)?) *(kb|mb|gb|tb|pb)$/i.exec(value);
    var amount = withUnit ? parseFloat(withUnit[1]) : parseInt(value, 10);
    if (isNaN(amount)) { return null; }
    var unit = withUnit ? SIZE_UNITS[withUnit[2].toLowerCase()] : 1;
    return Math.floor(unit * amount);
}

/**
 * The `limit` option of the JSON and urlencoded parsers: the given value, or the
 * maximum string length when the value gives a larger size (a larger body cannot be
 * read as a string anyway). Any other value is passed unchanged, so the parsers treat
 * it as before.
 * @param {*} value
 * @returns {*}
 */
function bodyParserLimit(value) {
    var size = bodyParserLimitBytes(value);
    return (typeof size === "number" && size > MAX_STRING_LENGTH) ? MAX_STRING_LENGTH : value;
}

/**
 * Initialise the module.
 * @param  {Object}     settings   The runtime settings
 * @param  {HTTPServer} _server     An instance of HTTP Server
 * @param  {Storage}    storage    An instance of Node-RED Storage
 * @param  {Runtime}    runtimeAPI An instance of Node-RED Runtime
 * @memberof @node-red/editor-api
 */
function init(settings,_server,storage,runtimeAPI) {
    server = _server;
    if (settings.httpAdminRoot !== false) {
        adminApp = apiUtil.createExpressApp(settings);

        if (settings.httpAdminMiddleware) {
            if (typeof settings.httpAdminMiddleware === "function" || Array.isArray(settings.httpAdminMiddleware)) {
                adminApp.use(settings.httpAdminMiddleware);
            }
        }

        auth.init(settings,storage);

        // the parsers read the body before authentication (as upstream); the limit is clamped (#63)
        var maxApiRequestSize = bodyParserLimit(settings.apiMaxLength || '5mb');
        adminApp.use(bodyParser.json({limit:maxApiRequestSize}));
        adminApp.use(bodyParser.urlencoded({limit:maxApiRequestSize,extended:true}));

        adminApp.get("/auth/login",auth.login,apiUtil.errorHandler);
        if (settings.adminAuth) {
            if (settings.adminAuth.type === "strategy") {
                auth.genericStrategy(adminApp,settings.adminAuth.strategy);
            } else if (settings.adminAuth.type === "credentials") {
                adminApp.use(passport.initialize());
                adminApp.post("/auth/token",
                    auth.ensureClientSecret,
                    auth.authenticateClient,
                    auth.getToken,
                    auth.errorHandler
                );
            } else if (settings.adminAuth.tokens) {
                adminApp.use(passport.initialize());
            }
            adminApp.post("/auth/revoke",auth.needsPermission(""),auth.revoke,apiUtil.errorHandler);
        }

        adminApp.post("/auth/token", auth.exchangeCodeForToken, apiUtil.errorHandler);

        // Editor
        if (!settings.disableEditor) {
            editor = require("./editor");
            var editorApp = editor.init(server, settings, runtimeAPI);
            adminApp.use(editorApp);
        }

        if (settings.httpAdminCors) {
            var corsHandler = cors(settings.httpAdminCors);
            adminApp.use(corsHandler);
        }

        var adminApiApp = require("./admin").init(settings, runtimeAPI);
        adminApp.use(adminApiApp);
    } else {
        adminApp = null;
    }
}

/**
 * Start the module.
 * @return {Promise} resolves when the application is ready to handle requests
 * @memberof @node-red/editor-api
 */
async function start() {
    if (editor) {
        return editor.start();
    }
}

/**
 * Stop the module.
 * @return {Promise} resolves when the application is stopped
 * @memberof @node-red/editor-api
 */
async function stop() {
    if (editor) {
        editor.stop();
    }
}

module.exports = {
    init,
    start,
    stop,

    /**
    * @memberof @node-red/editor-api
    * @mixes @node-red/editor-api_auth
    */
    auth: {
        needsPermission: auth.needsPermission,
        publicRoute: auth.publicRoute
    },
    /**
     * The Express app used to serve the Node-RED Editor
     * @type ExpressApplication
     * @memberof @node-red/editor-api
     */
    get httpAdmin() { return adminApp; }
};
